package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import tools.jackson.databind.node.ObjectNode;

/** city-capacity: reject creating an owner when the owner's city already contains 50+
 * owners (409). Fill a fresh, unique city to exactly 50, then the 51st in that city is rejected. */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void coreRejectsWhenCityAtCapacity() throws Exception {
		String city = "Cap" + seq();
		fillCity(city, 50);
		ObjectNode o = ownerNode();
		o.put("city", city);
		createOwner(o).andExpect(status().isConflict());
	}
}
===fillCity + helpers===
	protected String today() {
		return LocalDate.now().toString();
	}

	// --- payloads -----------------------------------------------------------

	/** A fully valid, fully unique owner — accepted by every rule at every checkpoint. */
	protected ObjectNode ownerNode() {
		ObjectNode o = om.createObjectNode();
		o.put("firstName", "Test");
		o.put("lastName", uniqueLastName());
		o.put("address", uniqueAddress());
		o.put("city", uniqueCity());
		o.put("telephone", uniqueTelephone());
		return o;
	}

	/** Owner payload plus a postcode. "2000" is in the NSW range and is accepted by cities with no
